import React, { useEffect } from "react";
import "./TestCard.css";
import { Link } from "react-router-dom";
import { HiOutlineClipboardList, HiClipboardCopy } from "react-icons/hi";
import { fetchTests } from "../actions/testActions";
import { connect } from "react-redux";
import { Skeleton } from "antd";

function TestCard(props) {
  let { tests, isLoading, studentClassName, trimLength } = props;
  if (tests)
    tests =
      tests.length > trimLength ? tests.slice(-trimLength).reverse() : tests;

  useEffect(() => {
    props.fetchTests(studentClassName);
  }, [studentClassName]); // added dependency to avoid warnings

  return (
    <>
      <div className="left__header red__header">
        <p className="left__header__text">
          {<HiOutlineClipboardList />} Today's Test
        </p>
      </div>
  
      <div className="left__body">
        {!isLoading && tests ? (
          <table className="test-table">
            <thead>
              <tr className="left__body__header">
                <th className="header__index">S.No</th>
                <th className="header__name">Test Name</th>
                <th className="header__time">Time</th>
                <th className="header__action">Action</th>
              
              </tr>
            </thead>
            <tbody>
              {tests.map((test, index) => (
                <tr key={index} className="left__body__test">
                  <td className="test__index">
                    <p className="index__box red__index">{index + 1}</p>
                  </td>
                  <td className="test__name">{test.testName}</td>
                 
                  <td className="test__time">{test.minutes} min</td>
                  <td className="test__icon">
                    <Link to="/attempt-test">
                      <HiClipboardCopy />
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <div className="skeleton">
            {Array(trimLength)
              .fill()
              .map((item, i) => (
                <div className="single-skeleton" key={i}>
                  <Skeleton.Avatar
                    className="avatar-skelton"
                    active={true}
                    size="default"
                    shape="square"
                  />
                  <Skeleton.Input
                    className="input-skelton"
                    active={true}
                    size="default"
                  />
                </div>
              ))}
          </div>
        )}
      </div>
    </>
  );
}

const mapStateToProps = (state) => {
  return {
    isLoading: state.tests.isLoadingTest,
    tests: state.tests.test,
  };
};

const mapDispatchToProps = (dispatch) => {
  return {
    fetchTests: (classID) => dispatch(fetchTests(classID)),
  };
};

export default connect(mapStateToProps, mapDispatchToProps)(TestCard);
